(2496522, 344442, 40370, '<td valign="top">Cute title. Nice image of creepy crawlies.</td>', 'Cute title. Nice image of creepy crawlies.', '2006-06-07 21:46:31.000000', NULL, 1),
(2496528, 343068, 40370, '<td valign="top">Bummer, wish you''d gotten a little closer though, too much road in the foreground, come on stop traffic next time :)</td>', 'Bummer, wish you''d gotten a little closer though, too much road in the foreground, come on stop traffic next time :)', '2006-06-07 21:47:59.000000', NULL, 1),
(2496539, 342482, 40370, '<td valign="top">Too much dirt, need more coin. How much is it worth? j/k No really how much?</td>', 'Too much dirt, need more coin. How much is it worth? j/k No really how much?', '2006-06-07 21:50:35.000000', NULL, 1),
(2496551, 344333, 40370, '<td valign="top">Precious. A bit soft in focus, though it''s amazing you captured a moment when the hummingbird isn''t fluttering a million miles an hour.</td>', 'Precious. A bit soft in focus, though it''s amazing you captured a moment when the hummingbird isn''t fluttering a million miles an hour.', '2006-06-07 21:53:53.000000', NULL, 1),
(2496553, 342554, 40370, '<td valign="top">Cute.</td>', 'Cute.', '2006-06-07 21:54:16.000000', NULL, 1),
(2496555, 344003, 40370, '<td valign="top">Cute.</td>', 'Cute.', '2006-06-07 21:54:48.000000', NULL, 1),
(2496561, 340839, 53668, '<td valign="top">My favorite!  Cute, and meets the challenge perfectly.</td>', 'My favorite!  Cute, and meets the challenge perfectly.', '2006-06-07 21:55:55.000000', NULL, 1),
(2496563, 342135, 40370, '<td valign="top">Interesting design ... I''d have liked a little more negative space at the top or more of the reflection at the bottom.</td>', 'Interesting design ... I''d have liked a little more negative space at the top or more of the reflection at the bottom.', '2006-06-07 21:56:49.000000', NULL, 1),
(2496572, 343086, 40370, '<td valign="top">Don''t we all need to wander upon one of these time to time. You got the focus right on your subject - good job.</td>', 'Don''t we all need to wander upon one of these time to time. You got the focus right on your subject - good job.', '2006-06-07 21:59:11.000000', NULL, 1),
(2496579, 343349, 40370, '<td valign="top">Oh ... how perfect this would be if the runner wasn''t only half in frame. Nice action shot.</td>', 'Oh ... how perfect this would be if the runner wasn''t only half in frame. Nice action shot.', '2006-06-07 22:00:43.000000', NULL, 1),
(2496595, 342834, 40370, '<td valign="top">Cherrios are so plain but you''ve done a good job sprucing them up. Good focus on the prize and overall DOF is good. Something I might have tried - the whole box as the backdrop, the line is a distraction to me as is the reflection on the side of the bowl. Still one of the better in the challenge.</td>', 'Cherrios are so plain but you''ve done a good job sprucing them up. Good focus on the prize and overall DOF is good. Something I might have tried - the whole box as the backdrop, the line is a distraction to me as is the reflection on the side of the bowl. Still one of the better in the challenge.', '2006-06-07 22:06:17.000000', NULL, 1),
(2496606, 344451, 40370, '<td valign="top">Bacon ... yum. Quite the post processing, it makes an unusual image even more peculiar, kind of "hammy".</td>', 'Bacon ... yum. Quite the post processing, it makes an unusual image even more peculiar, kind of "hammy".', '2006-06-07 22:09:15.000000', NULL, 1),
(2496612, 341669, 40370, '<td valign="top">Very sweet image. Curious to know if you decided to crop the mother''s head for the close-up or was this frame straight out-of-camera. Nice ride for sure.</td>', 'Very sweet image. Curious to know if you decided to crop the mother''s head for the close-up or was this frame straight out-of-camera. Nice ride for sure.', '2006-06-07 22:11:21.000000', NULL, 1),
(2496621, 344088, 40370, '<td valign="top">Something took a chunk out of his left wing, maybe a child''s butterfly net, but you got the true capture in a photograph. Excellent work.</td>', 'Something took a chunk out of his left wing, maybe a child''s butterfly net, but you got the true capture in a photograph. Excellent work.', '2006-06-07 22:14:41.000000', NULL, 1),
(2496623, 342056, 40370, '<td valign="top">Cute tail pointing right but what happened to his head, unfortunate framing.</td>', 'Cute tail pointing right but what happened to his head, unfortunate framing.', '2006-06-07 22:15:48.000000', NULL, 1),
(2496628, 344254, 40370, '<td valign="top">Kind of funny on the demented side.</td>', 'Kind of funny on the demented side.', '2006-06-07 22:18:08.000000', NULL, 1),
(2496640, 342390, 40370, '<td valign="top">Not done voting yet but possibly the most beautiful flower in the challenge, but I have a hard time feeling that flowers are all that unexpected. I will still give an extra point for stunning color.</td>', 'Not done voting yet but possibly the most beautiful flower in the challenge, but I have a hard time feeling that flowers are all that unexpected. I will still give an extra point for stunning color.', '2006-06-07 22:20:03.000000', NULL, 1),
(2496664, 341308, 40370, '<td valign="top">So is there a big grin on his face?</td>', 'So is there a big grin on his face?', '2006-06-07 22:23:07.000000', NULL, 1),
(2496690, 344457, 40370, '<td valign="top">Classic father and son moment. Maybe you have an "unexpectedly bald" Dad now. My son used to pull the Chums (sunglass retainer) on my husband''s head, it looked like he was trying to rein in his unruly horse.</td>', 'Classic father and son moment. Maybe you have an "unexpectedly bald" Dad now. My son used to pull the Chums (sunglass retainer) on my husband''s head, it looked like he was trying to rein in his unruly horse.', '2006-06-07 22:27:19.000000', NULL, 1),
(2496693, 342682, 56417, '<td valign="top">incredible</td>', 'incredible', '2006-06-07 22:27:42.000000', NULL, 1),
(2496697, 344448, 56417, '<td valign="top">very nice</td>', 'very nice', '2006-06-07 22:28:04.000000', NULL, 1),
(2496701, 341481, 56417, '<td valign="top">maybe a little out of focus?</td>', 'maybe a little out of focus?', '2006-06-07 22:28:38.000000', NULL, 1),
(2496706, 344251, 40370, '<td valign="top">Somebody feed that guy, look at those ribs, move over Kate Moss. Seriously, well not too, funny set-up, she actually looks truly surpised by the unexpected garbage man.</td>', 'Somebody feed that guy, look at those ribs, move over Kate Moss. Seriously, well not too, funny set-up, she actually looks truly surpised by the unexpected garbage man.', '2006-06-07 22:29:03.000000', NULL, 1),
(2496719, 341221, 56417, '<td valign="top">great shot</td>', 'great shot', '2006-06-07 22:29:55.000000', NULL, 1),
(2496720, 342247, 40370, '<td valign="top">Exceptional detail, you''ve made a virtually flat subject look very dimensional.</td>', 'Exceptional detail, you''ve made a virtually flat subject look very dimensional.', '2006-06-07 22:30:30.000000', NULL, 1),
(2496724, 340839, 56417, '<td valign="top">very cool</td>', 'very cool', '2006-06-07 22:30:46.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2496731, 344508, 56417, '<td valign="top">great shot!</td>', 'great shot!', '2006-06-07 22:31:55.000000', NULL, 1),
(2496818, 344348, 40370, '<td valign="top">Beautiful detail in the coloring.</td>', 'Beautiful detail in the coloring.', '2006-06-07 22:51:04.000000', NULL, 1),
(2496829, 344063, 40370, '<td valign="top">I like the B&amp;W aspect, the hands are beautifully captured but the bird looks glossy rather than feathered.</td>', 'I like the B&W aspect, the hands are beautifully captured but the bird looks glossy rather than feathered.', '2006-06-07 22:53:15.000000', NULL, 1),
(2496851, 344338, 40370, '<td valign="top">Almost missed the main attraction, hope other voters take the time to find the lizard in the midst of all the lines and color found in this image. Your title is a clue, but sometimes I am clueless :)</td>', 'Almost missed the main attraction, hope other voters take the time to find the lizard in the midst of all the lines and color found in this image. Your title is a clue, but sometimes I am clueless :)', '2006-06-07 22:59:16.000000', NULL, 1),
(2496859, 342682, 40370, '<td valign="top">Now that is serious weather. Do they have lightning proof capes for super brave photographers?</td>', 'Now that is serious weather. Do they have lightning proof capes for super brave photographers?', '2006-06-07 23:00:52.000000', NULL, 1),
(2496862, 344305, 40370, '<td valign="top">Ahh, even a double.</td>', 'Ahh, even a double.', '2006-06-07 23:01:23.000000', NULL, 1),
(2496873, 344448, 40370, '<td valign="top">It''s nice to see a panorama once in a while. Clouds are a bit blown out but the blues are gorgeous as is the unexpected find.</td>', 'It''s nice to see a panorama once in a while. Clouds are a bit blown out but the blues are gorgeous as is the unexpected find.', '2006-06-07 23:03:25.000000', NULL, 1),
