(2498896, 343033, 51538, '<td valign="top">Nice drama.  She''s running while speaking on the mobile, right?  If so, beats me.  I need to breath!</td>', 'Nice drama.  She''s running while speaking on the mobile, right?  If so, beats me.  I need to breath!', '2006-06-08 14:54:29.000000', NULL, 1),
(2498897, 344348, 51538, '<td valign="top">Nicest of the several grasshopper images I have seen lately.</td>', 'Nicest of the several grasshopper images I have seen lately.', '2006-06-08 14:54:52.000000', NULL, 1),
