(2498903, 341221, 51538, '<td valign="top">Unusual viewpoint for this type of shot (which are more common by the day) which makes this stand out.</td>', 'Unusual viewpoint for this type of shot (which are more common by the day) which makes this stand out.', '2006-06-08 14:55:45.000000', NULL, 1),
(2498904, 344448, 51538, '<td valign="top">Nice wide sky here.  Pity about the tree at the antler points.</td>', 'Nice wide sky here.  Pity about the tree at the antler points.', '2006-06-08 14:56:09.000000', NULL, 1),
(2498905, 343190, 51538, '<td valign="top">Nice focus on this pretty beasty.</td>', 'Nice focus on this pretty beasty.', '2006-06-08 14:56:32.000000', NULL, 1),
(2498906, 344329, 51538, '<td valign="top">A nice photo of an elegant bit of country.  Given more leaway with the rules, you could have brought out more detail in the clouds.</td>', 'A nice photo of an elegant bit of country.  Given more leaway with the rules, you could have brought out more detail in the clouds.', '2006-06-08 14:57:43.000000', NULL, 1),
(2498907, 342682, 51538, '<td valign="top">One of the better lightning photos I''ve seen of late.</td>', 'One of the better lightning photos I''ve seen of late.', '2006-06-08 14:58:06.000000', NULL, 1),
(2498910, 342738, 51538, '<td valign="top">I like this a lot but think it might have been better cropped a little.  IMO the left hand side dark grey mountain slope is a bit distracting.  But the tent-sized boulders and tents make an interesting subject.  I remember camping under a some 300 foot high sandstone cliffs at Hastings in England.  All night long it rained like the devil.  I was in the middle position in the small tent and that''s were the water puddled.  I was so wet and chilled that I got up early at 5:00am and we struck the tent and walked off down the beach.  It was still raining.  I turned round and looked at where we had been camping and at that moment a massive piece of the cliff suddenly broke away and plunged down directly on our erstwhile campsite.  That bit of cliff was as big as the largest boulder in your photo.  I''m careful where I camp these days! :-)</td>', 'I like this a lot but think it might have been better cropped a little.  IMO the left hand side dark grey mountain slope is a bit distracting.  But the tent-sized boulders and tents make an interesting subject.  I remember camping under a some 300 foot high sandstone cliffs at Hastings in England.  All night long it rained like the devil.  I was in the middle position in the small tent and that''s were the water puddled.  I was so wet and chilled that I got up early at 5:00am and we struck the tent and walked off down the beach.  It was still raining.  I turned round and looked at where we had been camping and at that moment a massive piece of the cliff suddenly broke away and plunged down directly on our erstwhile campsite.  That bit of cliff was as big as the largest boulder in your photo.  I''m careful where I camp these days! :-)', '2006-06-08 15:02:56.000000', NULL, 1),
(2498911, 343101, 51538, '<td valign="top">Good humour!</td>', 'Good humour!', '2006-06-08 15:03:17.000000', NULL, 1),
(2498912, 343931, 51538, '<td valign="top">Nice idea.  Possibly a beetle might have worked better.</td>', 'Nice idea.  Possibly a beetle might have worked better.', '2006-06-08 15:03:41.000000', NULL, 1),
(2498913, 344289, 40921, '<td valign="top">I like the composition, if you straightened the horizon and saturated the colors a bit I think it would increase your score. Good Luck</td>', 'I like the composition, if you straightened the horizon and saturated the colors a bit I think it would increase your score. Good Luck', '2006-06-08 15:04:06.000000', NULL, 1),
(2498915, 342668, 51538, '<td valign="top">The hue change does make the cycle stand out.  Given the basic rules, you did a good job.  Given advance rules it would have been better.  It''s a great opportunity for another shot.  Well done.</td>', 'The hue change does make the cycle stand out.  Given the basic rules, you did a good job.  Given advance rules it would have been better.  It''s a great opportunity for another shot.  Well done.', '2006-06-08 15:05:42.000000', NULL, 1),
(2498919, 342817, 51538, '<td valign="top">Don''t understand the title but the photo sure expresses unexpected!  Nice clarity!</td>', 'Don''t understand the title but the photo sure expresses unexpected!  Nice clarity!', '2006-06-08 15:06:16.000000', NULL, 1),
(2498921, 342919, 51538, '<td valign="top">Nice one with a good sense of fun!</td>', 'Nice one with a good sense of fun!', '2006-06-08 15:07:02.000000', NULL, 1),
(2498996, 343968, 45004, '<td valign="top">I like the water splash. It is so full. The hair has nice shape and detail. Nice job.</td>', 'I like the water splash. It is so full. The hair has nice shape and detail. Nice job.', '2006-06-08 15:31:45.000000', NULL, 1),
