INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2505289, 343968, 56673, '<td valign="top">Very cool!  (Pun intended).<br/> <br/>Great stop-action.  Good colors, fun effect with the water.  Very creative.</td>', 'Very cool!  (Pun intended). Great stop-action.  Good colors, fun effect with the water.  Very creative.', '2006-06-10 19:57:00.000000', NULL, 1),
(2505295, 342855, 56673, '<td valign="top">I think the subject had a lot of potential.  The hazy lighting caused some problems for you on this one.</td>', 'I think the subject had a lot of potential.  The hazy lighting caused some problems for you on this one.', '2006-06-10 20:02:19.000000', NULL, 1),
(2505301, 342056, 55746, '<td valign="top">He is very cute but I I belive you could have increased contrast and not cut off 1/4 of his head and that would have improved this greatly.</td>', 'He is very cute but I I belive you could have increased contrast and not cut off 1/4 of his head and that would have improved this greatly.', '2006-06-10 20:05:05.000000', NULL, 1),
(2505305, 341669, 55746, '<td valign="top">This is wonderful.  The rhythm of the water and the detail in the feathers are superb.  I would have prefered that this be taken in portrait rather than landscape so as not to cut off the mother''s head - otherwise fantastic! 10</td>', 'This is wonderful.  The rhythm of the water and the detail in the feathers are superb.  I would have prefered that this be taken in portrait rather than landscape so as not to cut off the mother''s head - otherwise fantastic! 10', '2006-06-10 20:08:37.000000', NULL, 1),
