(2513148, 344448, 60475, '<td valign="top">good composition</td>', 'good composition', '2006-06-13 15:18:06.000000', NULL, 1),
(2513184, 343553, 49460, '<td valign="top">This photo looks grainy (like a polaroid or snapshoot). The starburst appears to be super imposed; and the contrast could be improved by using levels to make the darkest areas of the image darker. That would bring out more details in the fathers face and maybe help the image seem crisper. The DVD rack in the background distracts from the father and his baby.</td>', 'This photo looks grainy (like a polaroid or snapshoot). The starburst appears to be super imposed; and the contrast could be improved by using levels to make the darkest areas of the image darker. That would bring out more details in the fathers face and maybe help the image seem crisper. The DVD rack in the background distracts from the father and his baby.', '2006-06-13 15:40:32.000000', NULL, 1),
(2513190, 344450, 49460, '<td valign="top">This photo seems a bit under exposed in most areas. The lamps come across as blobs of blown-out light and they don''t feel balanced. The large area of light reflecting on the tree in the upper left weights the photo unevenly and the patch of blue sky at the top corner doesn''t relate well to the rest of the image. Maybe a different crop would improve the framing but I suggest using a slower shutter speed and a tripod to brighten things up.</td>', 'This photo seems a bit under exposed in most areas. The lamps come across as blobs of blown-out light and they don''t feel balanced. The large area of light reflecting on the tree in the upper left weights the photo unevenly and the patch of blue sky at the top corner doesn''t relate well to the rest of the image. Maybe a different crop would improve the framing but I suggest using a slower shutter speed and a tripod to brighten things up.', '2006-06-13 15:45:53.000000', NULL, 1),
(2513193, 342554, 49460, '<td valign="top">This is cute! I love the idea and the only thing I might say to improve it would be that the light is maybe a bit harsh if you diffused it could make it better.</td>', 'This is cute! I love the idea and the only thing I might say to improve it would be that the light is maybe a bit harsh if you diffused it could make it better.', '2006-06-13 15:47:51.000000', NULL, 1),
(2513195, 342480, 49460, '<td valign="top">ha!</td>', 'ha!', '2006-06-13 15:48:31.000000', NULL, 1),
(2513198, 341308, 49460, '<td valign="top">This looks like a random snapshot. The guy is blurry-ish.</td>', 'This looks like a random snapshot. The guy is blurry-ish.', '2006-06-13 15:49:36.000000', NULL, 1),
(2513213, 344511, 49460, '<td valign="top">The image looks overexposed and all the molted light makes the grass chaotic. You might crop the bright corner to improve the image and bump up the shadows under levels. It''ll brighten the green and make the picture looks less overexposed.</td>', 'The image looks overexposed and all the molted light makes the grass chaotic. You might crop the bright corner to improve the image and bump up the shadows under levels. It''ll brighten the green and make the picture looks less overexposed.', '2006-06-13 15:55:26.000000', NULL, 1),
(2513214, 343101, 49460, '<td valign="top">Freaky!</td>', 'Freaky!', '2006-06-13 15:55:51.000000', NULL, 1);
