(2513478, 343033, 50695, '<td valign="top">those expressions are priceless.</td>', 'those expressions are priceless.', '2006-06-13 17:41:28.000000', NULL, 1),
(2513481, 340839, 50695, '<td valign="top">perfect execution of challenge.</td>', 'perfect execution of challenge.', '2006-06-13 17:41:50.000000', NULL, 1),
(2513483, 344508, 60443, '<td valign="top">Great! Love the black and white for this photograph.</td>', 'Great! Love the black and white for this photograph.', '2006-06-13 17:42:06.000000', NULL, 1),
